"""Generate packages/contracts/leads_pack.schema.json and leads_pack.ts from the models of the lead templates, the lead playbook and the knowledge base (job DR / A1). Same scheme as the other contracts (`make contracts`; a test fails if a file is stale)."""

from __future__ import annotations

import json
from typing import Any

from pydantic import BaseModel
from pydantic.json_schema import models_json_schema

from app.knowledge import models as k
from app.leadspack import models as m
from app.packs.contracts import _ts_type

HEADER = (
    "// GENERATED by `make contracts` from services/ai-api/app/leadspack/models.py and app/knowledge/models.py. Do not edit.\n"
    "// The lead templates, a workspace's lead playbook and its knowledge base (facts the assistant may state once approved).\n"
)
RESPONSES: list[type[BaseModel]] = [m.TemplatesOut, m.TemplateOut, m.PlaybookOut, k.SourcesOut, k.SourceOut, k.FactsOut, k.FactOut, k.DraftOut]
REQUESTS: list[type[BaseModel]] = [m.PlaybookBody, k.SourceIn, k.FactIn, k.FactEditIn, k.DecisionIn]


def build_schema() -> dict[str, Any]:
    _, defs = models_json_schema(
        [(model, "serialization") for model in RESPONSES] + [(model, "validation") for model in REQUESTS], ref_template="#/$defs/{model}"
    )
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": "leads_pack.schema.json",
        "title": "Leads pack, playbook and knowledge base (job DR / A1)",
        "description": "Generated from services/ai-api/app/leadspack/models.py and app/knowledge/models.py by `make contracts`.",
        "$defs": dict(sorted(defs.get("$defs", {}).items())),
    }


def schema_text() -> str:
    return json.dumps(build_schema(), indent=2, sort_keys=False) + "\n"


def ts_text() -> str:
    defs = build_schema()["$defs"]
    lines = [HEADER]
    for name, node in defs.items():
        ts_name = name.replace("_", "")
        if "enum" in node:
            lines.append(f"export type {ts_name} = {_ts_type(node)};\n")
            continue
        props = node.get("properties", {})
        required = set(node.get("required", []))
        body = []
        for prop, spec in props.items():
            optional = "" if prop in required else "?"
            body.append(f"  {prop}{optional}: {_ts_type(spec)};")
        lines.append(f"export interface {ts_name} {{\n" + "\n".join(body) + "\n}\n")
    return "\n".join(lines)
